<?php

namespace MongoDB\Driver;

/**
 * <div id="class.mongodb-driver-serverdescription" class="reference"> <h1 class="title">The MongoDB\Driver\ServerDescription class</h1>  <div class="partintro"><p class="verinfo">(mongodb &gt;=1.13.0)</p>  <div class="section" id="mongodb-driver-serverdescription.intro">   <h2 class="title">简介</h2>   <p class="simpara">    The <span class="classname"><strong class="classname">MongoDB\Driver\ServerDescription</strong></span> class is a value    object that represents a server to which the driver is connected. Instances    of this class are returned by    <span class="function">{@link MongoDB\Driver\Server::getServerDescription()}</span> and    <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-serverchangedevent.php" class="classname">MongoDB\Driver\Monitoring\ServerChangedEvent</a></span> methods.   </p>  </div>  <div class="section" id="mongodb-driver-serverdescription.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="modifier">final</span>     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">MongoDB\Driver\ServerDescription</strong>     </span>     {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 常量 </div>    <div class="fieldsynopsis">     <span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-serverdescription.php#mongodb-driver-serverdescription.constants.type-unknown"><var class="varname">TYPE_UNKNOWN</var></a></var><span class="initializer"> = "Unknown"</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-serverdescription.php#mongodb-driver-serverdescription.constants.type-standalone"><var class="varname">TYPE_STANDALONE</var></a></var><span class="initializer"> = "Standalone"</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-serverdescription.php#mongodb-driver-serverdescription.constants.type-mongos"><var class="varname">TYPE_MONGOS</var></a></var><span class="initializer"> = "Mongos"</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-serverdescription.php#mongodb-driver-serverdescription.constants.type-possible-primary"><var class="varname">TYPE_POSSIBLE_PRIMARY</var></a></var><span class="initializer"> = "PossiblePrimary"</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-serverdescription.php#mongodb-driver-serverdescription.constants.type-rs-primary"><var class="varname">TYPE_RS_PRIMARY</var></a></var><span class="initializer"> = "RSPrimary"</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-serverdescription.php#mongodb-driver-serverdescription.constants.type-rs-secondary"><var class="varname">TYPE_RS_SECONDARY</var></a></var><span class="initializer"> = "RSSecondary"</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-serverdescription.php#mongodb-driver-serverdescription.constants.type-rs-arbiter"><var class="varname">TYPE_RS_ARBITER</var></a></var><span class="initializer"> = "RSArbiter"</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-serverdescription.php#mongodb-driver-serverdescription.constants.type-rs-other"><var class="varname">TYPE_RS_OTHER</var></a></var><span class="initializer"> = "RSOther"</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-serverdescription.php#mongodb-driver-serverdescription.constants.type-rs-ghost"><var class="varname">TYPE_RS_GHOST</var></a></var><span class="initializer"> = "RSGhost"</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-serverdescription.php#mongodb-driver-serverdescription.constants.type-load-balancer"><var class="varname">TYPE_LOAD_BALANCER</var></a></var><span class="initializer"> = "LoadBalancer"</span>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-serverdescription.gethelloresponse.php" class="methodname" style="color:#CC7832">getHelloResponse</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-serverdescription.gethost.php" class="methodname" style="color:#CC7832">getHost</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-serverdescription.getlastupdatetime.php" class="methodname" style="color:#CC7832">getLastUpdateTime</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-serverdescription.getport.php" class="methodname" style="color:#CC7832">getPort</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-serverdescription.getroundtriptime.php" class="methodname" style="color:#CC7832">getRoundTripTime</a></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-serverdescription.gettype.php" class="methodname" style="color:#CC7832">getType</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>   }</div>  </div>  <div class="section" id="mongodb-driver-serverdescription.constants">   <h2 class="title">预定义常量</h2>   <dl>         <dt id="mongodb-driver-serverdescription.constants.type-unknown"><strong><span>{@link MongoDB\Driver\ServerDescription::TYPE_UNKNOWN}</span></strong></dt>     <dd>      <span class="simpara">Unknown server type, returned by <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\ServerDescription::getType()}</span>.</span>     </dd>             <dt id="mongodb-driver-serverdescription.constants.type-standalone"><strong><span>{@link MongoDB\Driver\ServerDescription::TYPE_STANDALONE}</span></strong></dt>     <dd>      <span class="simpara">Standalone server type, returned by <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\ServerDescription::getType()}</span>.</span>     </dd>             <dt id="mongodb-driver-serverdescription.constants.type-mongos"><strong><span>{@link MongoDB\Driver\ServerDescription::TYPE_MONGOS}</span></strong></dt>     <dd>      <span class="simpara">Mongos server type, returned by <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\ServerDescription::getType()}</span>.</span>     </dd>             <dt id="mongodb-driver-serverdescription.constants.type-possible-primary"><strong><span>{@link MongoDB\Driver\ServerDescription::TYPE_POSSIBLE_PRIMARY}</span></strong></dt>     <dd>      <span class="simpara">Replica set possible primary server type, returned by <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\ServerDescription::getType()}</span>.</span>      <span class="simpara">A server may be identified as a possible primary if it has not yet been checked but another memory of the replica set thinks it is the primary.</span>     </dd>             <dt id="mongodb-driver-serverdescription.constants.type-rs-primary"><strong><span>{@link MongoDB\Driver\ServerDescription::TYPE_RS_PRIMARY}</span></strong></dt>     <dd>      <span class="simpara">Replica set primary server type, returned by <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\ServerDescription::getType()}</span>.</span>     </dd>             <dt id="mongodb-driver-serverdescription.constants.type-rs-secondary"><strong><span>{@link MongoDB\Driver\ServerDescription::TYPE_RS_SECONDARY}</span></strong></dt>     <dd>      <span class="simpara">Replica set secondary server type, returned by <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\ServerDescription::getType()}</span>.</span>     </dd>             <dt id="mongodb-driver-serverdescription.constants.type-rs-arbiter"><strong><span>{@link MongoDB\Driver\ServerDescription::TYPE_RS_ARBITER}</span></strong></dt>     <dd>      <span class="simpara">Replica set arbiter server type, returned by <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\ServerDescription::getType()}</span>.</span>     </dd>             <dt id="mongodb-driver-serverdescription.constants.type-rs-other"><strong><span>{@link MongoDB\Driver\ServerDescription::TYPE_RS_OTHER}</span></strong></dt>     <dd>      <span class="simpara">Replica set other server type, returned by <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\ServerDescription::getType()}</span>.</span>      <span class="simpara">Such servers may be hidden, starting up, or recovering. They cannot be queried, but their hosts lists are useful for discovering the current replica set configuration.</span>     </dd>             <dt id="mongodb-driver-serverdescription.constants.type-rs-ghost"><strong><span>{@link MongoDB\Driver\ServerDescription::TYPE_RS_GHOST}</span></strong></dt>     <dd>      <span class="simpara">Replica set ghost server type, returned by <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\ServerDescription::getType()}</span>.</span>      <span class="simpara">Servers may be identified as such in at least three situations: briefly during server startup; in an uninitialized replica set; or when the server is shunned (i.e. removed from the replica set config). They cannot be queried, nor can their host list be used to discover the current replica set configuration; however, the client may monitor this server in hope that it transitions to a more useful state.</span>     </dd>             <dt id="mongodb-driver-serverdescription.constants.type-load-balancer"><strong><span>{@link MongoDB\Driver\ServerDescription::TYPE_LOAD_BALANCER}</span></strong></dt>     <dd>      <span class="simpara">Load balancer server type, returned by <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\ServerDescription::getType()}</span>.</span>     </dd>       </dl>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\Driver\ServerDescription::getHelloResponse} — Returns the server's most recent "hello" response</li><li>{@link MongoDB\Driver\ServerDescription::getHost} — Returns the hostname of this server</li><li>{@link MongoDB\Driver\ServerDescription::getLastUpdateTime} — Returns the server's last update time in microseconds</li><li>{@link MongoDB\Driver\ServerDescription::getPort} — Returns the port on which this server is listening</li><li>{@link MongoDB\Driver\ServerDescription::getRoundTripTime} — Returns the server's round trip time in milliseconds</li><li>{@link MongoDB\Driver\ServerDescription::getType} — Returns a string denoting the type of this server</li></ul></div>
 * 
 * @since 1.13.0
 */
final class ServerDescription
{
    public const TYPE_UNKNOWN = 'Unknown';
    public const TYPE_STANDALONE = 'Standalone';
    public const TYPE_MONGOS = 'Mongos';
    public const TYPE_POSSIBLE_PRIMARY = 'PossiblePrimary';
    public const TYPE_RS_PRIMARY = 'RSPrimary';
    public const TYPE_RS_SECONDARY = 'RSSecondary';
    public const TYPE_RS_ARBITER = 'RSArbiter';
    public const TYPE_RS_OTHER = 'RSOther';
    public const TYPE_RS_GHOST = 'RSGhost';
    public const TYPE_LOAD_BALANCER = 'LoadBalancer';


    final private function __construct() {}

    /**
 * <div id="mongodb-driver-serverdescription.gethelloresponse" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\ServerDescription::getHelloResponse</h1>  <p class="verinfo">(mongodb &gt;=1.13.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\ServerDescription::getHelloResponse</span> — <span class="dc-title">Returns the server's most recent "hello" response</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-serverdescription.gethelloresponse-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\ServerDescription::getHelloResponse</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>  <p class="simpara">   Returns an array of information describing the server. This array is derived   from the most recent (at the time the   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-serverdescription.php" class="classname">MongoDB\Driver\ServerDescription</a></span> was constructed)   <a href="https://www.mongodb.com/docs/manual/reference/command/hello/" class="link external">»&nbsp;hello</a>   command response obtained through   <a href="https://github.com/mongodb/specifications/blob/master/source/server-discovery-and-monitoring/server-discovery-and-monitoring.md" class="link external">»&nbsp;server monitoring</a>.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    When the driver is connected to a load balancer, this method will return an    empty array since load balancers are not monitored. This is in contrast to    <span class="function">{@link MongoDB\Driver\Server::getInfo()}</span>, which would return the    backing server's    <a href="https://www.mongodb.com/docs/manual/reference/command/hello/" class="link external">»&nbsp;hello</a>    command response from the initial connection handshake.   </span>  </p></blockquote> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-serverdescription.gethelloresponse-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-serverdescription.gethelloresponse-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns an array of information describing this server.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-serverdescription.gethelloresponse-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-serverdescription.gethelloresponse-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link MongoDB\Driver\Server::getInfo()} - Returns an array of information describing this server</span></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/command/hello/" class="link external">»&nbsp;hello</a> command in the MongoDB manual</li>   <li><a href="https://github.com/mongodb/specifications/blob/master/source/server-discovery-and-monitoring/server-discovery-and-monitoring.md" class="link external">»&nbsp;Server Discovery and Monitoring Specification</a></li>  </ul> </div></div>
 * 
     * Returns the server's most recent "hello" response
     * @link https://www.php.net/manual/en/mongodb-driver-serverdescription.gethelloresponse.php
     */
    final public function getHelloResponse(): array {}

    /**
 * <div id="mongodb-driver-serverdescription.gethost" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\ServerDescription::getHost</h1>  <p class="verinfo">(mongodb &gt;=1.13.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\ServerDescription::getHost</span> — <span class="dc-title">Returns the hostname of this server</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-serverdescription.gethost-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\ServerDescription::getHost</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="simpara">   Returns the hostname of this server.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-serverdescription.gethost-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-serverdescription.gethost-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the hostname of this server.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-serverdescription.gethost-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-serverdescription.gethost-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link MongoDB\Driver\Server::getHost()} - Returns the hostname of this server</span></li>  </ul> </div></div>
 * 
     * Returns the hostname of this server
     * @link https://www.php.net/manual/en/mongodb-driver-serverdescription.gethost.php
     */
    final public function getHost(): string {}

    /**
 * <div id="mongodb-driver-serverdescription.getlastupdatetime" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\ServerDescription::getLastUpdateTime</h1>  <p class="verinfo">(mongodb &gt;=1.13.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\ServerDescription::getLastUpdateTime</span> — <span class="dc-title">Returns the server's last update time in microseconds</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-serverdescription.getlastupdatetime-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\ServerDescription::getLastUpdateTime</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>  <p class="simpara">   Returns the server's last update time in microseconds.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    The returned value is a monotonic timestamp, which starts at an arbitrary    point. As such, it is only suitable to compare with other return values from    <span class="function"><strong style="color:#CC7832">MongoDB\Driver\ServerDescription::getLastUpdateTime()</strong></span>.   </span>  </p></blockquote> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-serverdescription.getlastupdatetime-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-serverdescription.getlastupdatetime-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the server's last update time in microseconds.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-serverdescription.getlastupdatetime-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div></div>
 * 
     * Returns the server's last update time in microseconds
     * @link https://www.php.net/manual/en/mongodb-driver-serverdescription.getlastupdatetime.php
     */
